The module models reservations against an in-memory stock ledger. `StockLedger` accepts initial rows containing a nonblank SKU and a finite, non-negative integer quantity. Duplicate SKUs and malformed rows must throw `RangeError`; construction must not retain row references. `available` returns the current quantity or zero for an unknown SKU. `reserve` requires a nonblank reservation ID, at least one line, unique nonblank SKUs, and positive integer quantities. It must throw `RangeError` without changing state if validation fails, stock is insufficient, or the reservation ID already exists. Successful reservation deducts stock. `cancel` returns false for an unknown ID; otherwise it restores every reserved quantity exactly once and returns true. `getReservation` returns an independent deep copy or undefined. Ordering of reservation lines must be preserved.

Known-bad source:

export interface StockRow {
  sku: string;
  quantity: number;
}

export interface ReservationLine {
  sku: string;
  quantity: number;
}

function validQuantity(value: number, positive: boolean): boolean {
  return Number.isInteger(value) && Number.isFinite(value) && (positive ? value > 0 : value >= 0);
}

export class StockLedger {
  private readonly stock = new Map<string, number>();
  private readonly reservations = new Map<string, ReservationLine[]>();

  public constructor(rows: readonly StockRow[]) {
    for (const row of rows) {
      if (row.sku.trim().length === 0 || !validQuantity(row.quantity, false) || this.stock.has(row.sku)) {
        throw new RangeError("invalid stock row");
      }
      this.stock.set(row.sku, row.quantity);
    }
  }

  public available(sku: string): number {
    return this.stock.get(sku) ?? 0;
  }

  public reserve(id: string, lines: readonly ReservationLine[]): void {
    if (id.trim().length === 0 || lines.length === 0 || this.reservations.has(id)) {
      throw new RangeError("invalid reservation");
    }

    const seen = new Set<string>();
    for (const line of lines) {
      if (line.sku.trim().length === 0 || !validQuantity(line.quantity, true) || seen.has(line.sku)) {
        throw new RangeError("invalid reservation line");
      }
      seen.add(line.sku);
      if ((this.stock.get(line.sku) ?? 0) < line.quantity) {
        throw new RangeError("insufficient stock");
      }
    }

    const copy = lines.map((line) => ({ sku: line.sku, quantity: line.quantity }));
    for (const line of copy) {
      this.stock.set(line.sku, (this.stock.get(line.sku) ?? 0) - line.quantity);
    }
    this.reservations.set(id, copy);
  }

  public cancel(id: string): boolean {
    const lines = this.reservations.get(id);
    if (lines === undefined) {
      return false;
    }
    for (const line of lines) {
      this.stock.set(line.sku, (this.stock.get(line.sku) ?? 0) + 1);
    }
    this.reservations.delete(id);
    return true;
  }

  public getReservation(id: string): ReservationLine[] | undefined {
    const lines = this.reservations.get(id);
    return lines?.map((line) => ({ sku: line.sku, quantity: line.quantity }));
  }
}

