import { StockLedger, type StockRow, type ReservationLine } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function expectRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught: unknown) { error = caught; }
  assert(error instanceof RangeError, message);
}

const rows: StockRow[] = [{ sku: "A", quantity: 5 }, { sku: "B", quantity: 3 }, { sku: "ZERO", quantity: 0 }];
const ledger = new StockLedger(rows);
rows[0].sku = "CHANGED";
rows[0].quantity = 999;
equal(ledger.available("A"), 5, "constructor copies rows");
equal(ledger.available("CHANGED"), 0, "mutated source row not retained");
equal(ledger.available("missing"), 0, "unknown stock is zero");
equal(ledger.available("ZERO"), 0, "zero stock accepted");

expectRangeError(() => new StockLedger([{ sku: " ", quantity: 1 }]), "blank SKU rejected");
expectRangeError(() => new StockLedger([{ sku: "A", quantity: -1 }]), "negative initial quantity rejected");
expectRangeError(() => new StockLedger([{ sku: "A", quantity: 1.5 }]), "fractional initial quantity rejected");
expectRangeError(() => new StockLedger([{ sku: "A", quantity: Number.POSITIVE_INFINITY }]), "infinite initial quantity rejected");
expectRangeError(() => new StockLedger([{ sku: "A", quantity: 1 }, { sku: "A", quantity: 2 }]), "duplicate initial SKU rejected");

const lines: ReservationLine[] = [{ sku: "B", quantity: 2 }, { sku: "A", quantity: 4 }];
ledger.reserve("r1", lines);
equal(ledger.available("A"), 1, "reservation deducts A");
equal(ledger.available("B"), 1, "reservation deducts B");
lines[0].quantity = 99;
lines.reverse();
const stored = ledger.getReservation("r1");
assert(stored !== undefined, "stored reservation returned");
equal(stored?.[0].sku, "B", "line order preserved");
equal(stored?.[0].quantity, 2, "reservation lines copied on input");
equal(stored?.[1].sku, "A", "second line order preserved");
if (stored !== undefined) stored[0].quantity = 77;
equal(ledger.getReservation("r1")?.[0].quantity, 2, "getReservation deep copies lines");
equal(ledger.getReservation("unknown"), undefined, "unknown reservation omitted");

const beforeA = ledger.available("A");
const beforeB = ledger.available("B");
expectRangeError(() => ledger.reserve("bad", [{ sku: "A", quantity: 1 }, { sku: "B", quantity: 2 }]), "insufficient reservation rejected");
equal(ledger.available("A"), beforeA, "insufficient reservation does not partially deduct A");
equal(ledger.available("B"), beforeB, "insufficient reservation does not partially deduct B");
expectRangeError(() => ledger.reserve("r1", [{ sku: "A", quantity: 1 }]), "duplicate reservation ID rejected");
expectRangeError(() => ledger.reserve(" ", [{ sku: "A", quantity: 1 }]), "blank reservation ID rejected");
expectRangeError(() => ledger.reserve("empty", []), "empty reservation rejected");
expectRangeError(() => ledger.reserve("duplicate-lines", [{ sku: "A", quantity: 1 }, { sku: "A", quantity: 1 }]), "duplicate line SKU rejected");
expectRangeError(() => ledger.reserve("zero-line", [{ sku: "A", quantity: 0 }]), "zero reservation quantity rejected");
expectRangeError(() => ledger.reserve("unknown-stock", [{ sku: "NOPE", quantity: 1 }]), "unknown stock is insufficient");

assert(ledger.cancel("r1"), "known reservation cancels");
equal(ledger.available("A"), 5, "cancel restores exact A quantity");
equal(ledger.available("B"), 3, "cancel restores exact B quantity");
assert(!ledger.cancel("r1"), "reservation restored only once");
equal(ledger.available("A"), 5, "second cancellation changes nothing");

